import React, {useEffect, useMemo, useState} from 'react';
import {createRoot} from 'react-dom/client';
import {Activity, ArrowDownToLine, ArrowRight, ArrowUpRight, BarChart3, BookOpen, Check, CheckCircle2, ChevronDown, ChevronRight, CircleHelp, Clock3, Database, FileText, FlaskConical, GitBranch, Layers3, Leaf, Loader2, MessageSquareText, MoreHorizontal, Pause, Play, Plus, Search, Settings2, ShieldCheck, Sparkles, Target, TrendingUp, X, XCircle, AlertCircle, Wallet, Workflow} from 'lucide-react';
import {ResponsiveContainer, AreaChart, Area, CartesianGrid, XAxis, YAxis, Tooltip, LineChart, Line, BarChart, Bar, ReferenceLine} from 'recharts';
import './styles.css';
import {ResearchProgress} from './components/ResearchProgress';
import {ResearchFeedback,ResearchRules} from './components/ResearchFeedback';

type Row = Record<string, any>;
const nav = [{id:'tasks',label:'任务设置',icon:FlaskConical},{id:'library',label:'资料库',icon:BookOpen},{id:'debate',label:'辩论与版本',icon:MessageSquareText},{id:'results',label:'实验结果',icon:BarChart3},{id:'factors',label:'因子库',icon:Layers3},{id:'settings',label:'数据与模型',icon:Settings2}];
const statuses:Row={awaiting_approval:'等待你的决策',queued:'等待执行',preflight:'核验数据',proposing:'独立提案中',debating:'交叉辩论中',evaluating:'代码验证中',final_testing:'最终测试中',completed:'已完成',rejected:'已淘汰',needs_attention:'需要处理',paused:'已暂停',budget_exhausted:'预算已用完'};
const stageName:Row={development:'开发区',validation:'验证区',final:'最终测试',recent:'近期补充',forward:'前瞻观察'};
const roles:Row={value:'价值 / 质量',growth:'成长 / 财务动量',engineer:'因子工程师',system:'流程控制器'};
const pct=(n:any,d=1)=>n==null?'—':`${(Number(n)*100).toFixed(d)}%`;
const num=(n:any,d=3)=>n==null?'—':Number(n).toFixed(d);
const money=(n:any)=>`¥${Number(n||0).toFixed(2)}`;
const date=(s:any)=>s?new Date(s).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
async function api(path:string,options:RequestInit={}){const response=await fetch('/api'+path,{...options,headers:options.body instanceof FormData?undefined:{'Content-Type':'application/json',...options.headers}});const result=await response.json();if(!response.ok)throw new Error(typeof result.detail==='string'?result.detail:JSON.stringify(result.detail||result));return result;}
const post=(path:string,body:Row={})=>api(path,{method:'POST',body:JSON.stringify(body)});

function Pill({children,tone='neutral'}:{children:React.ReactNode,tone?:string}){return <span className={'pill '+tone}>{children}</span>}
function Empty({icon:Icon=FlaskConical,title,text,action}:{icon?:any,title:string,text:string,action?:React.ReactNode}){return <div className="empty"><span className="empty-icon"><Icon size={26}/></span><h3>{title}</h3><p>{text}</p>{action}</div>}
function Field({label,children,hint}:{label:string,children:React.ReactNode,hint?:string}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Modal({title,subtitle,onClose,children,wide=false}:{title:string,subtitle?:string,onClose:()=>void,children:React.ReactNode,wide?:boolean}){return <div className="modal-backdrop" onMouseDown={onClose}><section className={'modal '+(wide?'wide':'')} role="dialog" aria-modal="true" aria-label={title} onMouseDown={e=>e.stopPropagation()}><header><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className="icon-button" onClick={onClose} aria-label="关闭"><X size={20}/></button></header>{children}</section></div>}

function App(){
 const [page,setPage]=useState('tasks'),[tasks,setTasks]=useState<Row[]>([]),[overview,setOverview]=useState<Row>({}),[profiles,setProfiles]=useState<Row[]>([]),[datasets,setDatasets]=useState<Row[]>([]),[docs,setDocs]=useState<Row[]>([]),[factors,setFactors]=useState<Row[]>([]),[providers,setProviders]=useState<Row>({providers:[]}),[benchmarks,setBenchmarks]=useState<Row[]>([]),[jobs,setJobs]=useState<Row[]>([]);
 const [activeId,setActiveId]=useState(localStorage.getItem('factor-active')||''),[task,setTask]=useState<Row|null>(null),[modal,setModal]=useState(''),[busy,setBusy]=useState(false),[notice,setNotice]=useState<{text:string,error:boolean}|null>(null),[filter,setFilter]=useState('');
 const [researchSummary,setResearchSummary]=useState<Row|null>(null);
 const [selectedExperiment,setSelectedExperiment]=useState(''),[horizon,setHorizon]=useState('60'),[split,setSplit]=useState('validation');
 const [decision,setDecision]=useState<Row>({action:'approve',reason:''}),[newTask,setNewTask]=useState<Row>({name:'现金流质量与经营改善',objective:'寻找具有经济解释、跨行业稳定的基本面因子，检验现金流质量与经营改善的增量信息。',mode:'demo',architecture:'debate',dataset_id:'demo-v1',budget_cny:0,model_profile_id:null});
 const [newProfile,setNewProfile]=useState<Row>({name:'',protocol:'responses',base_url:'https://api.openai.com/v1',model:'',secret_name:'research-model',input_cny_per_million:0,output_cny_per_million:0,max_output_tokens:6000});
 const [newDoc,setNewDoc]=useState<Row>({title:'',url:'',publisher:'',published_date:'',version_date:'',evidence_note:'',text:'',verified:false}),[query,setQuery]=useState('盈利质量 现金流 因子'),[searchResults,setSearchResults]=useState<Row[]>([]);
 const [importForm,setImportForm]=useState<Row>({dataset_id:'',source:'',pit_verified:false}),[financialFile,setFinancialFile]=useState<File|null>(null),[marketFile,setMarketFile]=useState<File|null>(null),[sampleProvider,setSampleProvider]=useState('ricequant'),[sampleSymbols,setSampleSymbols]=useState('000001.XSHE'),[benchmarkSelection,setBenchmarkSelection]=useState<string[]>([]),[benchmarkBudget,setBenchmarkBudget]=useState(10);

 const [comparisons,setComparisons]=useState<Row[]>([]),[observationDataset,setObservationDataset]=useState(''),[editingTask,setEditingTask]=useState(false);
 async function refresh(){try{const all=await Promise.all([api('/tasks'),api('/overview'),api('/profiles'),api('/datasets'),api('/documents'),api('/factors'),api('/providers'),api('/benchmarks'),api('/jobs'),api('/comparisons')]);setTasks(all[0]);setOverview(all[1]);setProfiles(all[2]);setDatasets(all[3]);setDocs(all[4]);setFactors(all[5]);setProviders(all[6]);setBenchmarks(all[7]);setJobs(all[8]);setComparisons(all[9]);}catch(e:any){setNotice({text:e.message||'本机服务暂未连接',error:true});}}
 useEffect(()=>{window.scrollTo({top:0,left:0})},[page]);
 async function refreshTask(){if(activeId){try{const [detail,summary]=await Promise.all([api('/tasks/'+activeId),api('/tasks/'+activeId+'/research-summary')]);setTask(detail);setResearchSummary(summary)}catch{setTask(null);setResearchSummary(null)}}else{setTask(null);setResearchSummary(null)}}
 useEffect(()=>{refresh();const timer=setInterval(refresh,5000);return()=>clearInterval(timer)},[]);
 useEffect(()=>{localStorage.setItem('factor-active',activeId);refreshTask();setSelectedExperiment('');const timer=setInterval(refreshTask,4000);return()=>clearInterval(timer)},[activeId]);
 useEffect(()=>{if(notice&&!notice.error){const t=setTimeout(()=>setNotice(null),5000);return()=>clearTimeout(t)}},[notice]);
 const perform=async(fn:()=>Promise<any>,message?:string)=>{setBusy(true);try{await fn();await refresh();await refreshTask();if(message)setNotice({text:message,error:false})}catch(e:any){setNotice({text:e.message,error:true})}finally{setBusy(false)}};
 const activeDataset=datasets.find(d=>d.id===task?.config?.dataset_id);
 const experiments=useMemo(()=>[...(task?.experiments||[]),...(task?.final_results||[])],[task]);
 const matchingExperiments=experiments.filter(e=>e.split===split);
 const selected=matchingExperiments.find(e=>e.id===selectedExperiment)||matchingExperiments.find(e=>e.status==='complete'&&!e.hypothesis_id.startsWith('baseline:'))||matchingExperiments[0];
 const report=selected?.payload;
 const hypotheses=(task?.artifacts||[]).filter((a:Row)=>a.kind==='hypothesis');
 const leafHypotheses=hypotheses.filter((h:Row)=>!hypotheses.some((other:Row)=>other.parent_id===h.id));
 const outputs=(task?.artifacts||[]).filter((a:Row)=>a.kind==='agent_output');
 const titleFor=(id:string)=>id.startsWith('baseline:')?id.slice(9):hypotheses.find((h:Row)=>h.id===id)?.payload.title||'候选因子';
 const selectedTask=tasks.find(t=>t.id===activeId);
 const isDemo=task?.config?.mode==='demo';
 const running=task&&['queued','preflight','proposing','debating','evaluating','final_testing'].includes(task.status);
 const pageCopy:Row={tasks:['研究工作台','从一个有依据的假设，开始一轮可复查的研究。'],library:['研究资料库','让每个论点有出处，让每份资料留在正确的时间里。'],debate:['不同视角，共同求证','查看独立提案、交叉批判，以及每一次有理由的修改。'],results:['让证据回答问题','同时查看预测能力、执行表现与失败记录。'],factors:['因子观察库','保留有依据的发现，也保留它们适用的边界。'],settings:['数据与模型','先验证质量与成本，再决定研究的基础配置。']};

 const create=()=>perform(async()=>{const result=editingTask?await api('/tasks/'+activeId,{method:'PUT',body:JSON.stringify(newTask)}):await post('/tasks',{...newTask,workflow_version:2});setEditingTask(false);setActiveId(result.id);setPage('tasks');setModal('')},'任务已创建，请在环节 1 确认后开始。');
 const submitDecision=()=>perform(async()=>{await post(`/tasks/${activeId}/decisions`,{gate:task!.gate,action:decision.action,reason:decision.reason,expected_version:task!.version,request_id:crypto.randomUUID()});setModal('')},'决定已记录，后台将继续处理。');
 const openDecision=(action=task?.gate===10?'observe':'approve')=>{setDecision({action,reason:''});setModal('decision')};
 const saveProfile=()=>perform(async()=>{await post('/profiles',newProfile);setModal('')},'模型配置已保存；密钥通过本机凭据工具设置。');
 const saveDoc=()=>perform(async()=>{await post('/documents',newDoc);setModal('')},'资料已保存，系统将按版本日期和核验状态筛选。');

 return <div className="app-shell">
  <aside className="sidebar">
   <a className="brand" href="#" onClick={e=>{e.preventDefault();setPage('tasks')}}><span className="brand-mark"><Activity size={23}/></span><div><strong>因子研究室</strong><span>FUNDAMENTAL LAB</span></div></a>
   <div className="workspace-chip"><span className="workspace-avatar">研</span><div><strong>我的研究空间</strong><small>本机工作台</small></div><ChevronDown size={15}/></div>
   <div className="nav-caption">研究空间</div><nav>{nav.map(({id,label,icon:Icon})=><button key={id} className={page===id?'active':''} onClick={()=>setPage(id)}><Icon size={18}/><span>{label}</span>{id==='tasks'&&overview.awaiting>0&&<b className="nav-count">{overview.awaiting}</b>}</button>)}</nav>
   <div className="sidebar-note"><span className="tiny-heading"><ShieldCheck size={16}/> 研究有边界</span><p>先提出可以被推翻的假设，<br/>再让数据给出答案。</p><div><i/> 本机计算 · 过程留痕</div></div>
   <button className="help-link" onClick={()=>setModal('help')}><CircleHelp size={17}/> 使用指南 <ArrowUpRight size={14}/></button><div className="sidebar-footer"><span className="user-avatar">我</span><div>个人研究员<small>LOCAL WORKSPACE</small></div><span className="version">v0.1</span></div>
  </aside>
  <div className="main-shell">
   <header className="topbar"><div className="breadcrumb">研究空间 <ChevronRight size={13}/> <span>{nav.find(n=>n.id===page)?.label}</span></div><div className="topbar-right"><span className="connection"><i className={overview.health?.worker_running?'':'offline'}/>{overview.health?.worker_running?'研究引擎已连接':'研究引擎离线'}</span><span className="topbar-divider"/><button className="icon-button" onClick={()=>{setPage('tasks');setFilter('待审核')}} aria-label="查看待审核任务"><Clock3 size={18}/>{overview.awaiting>0&&<span className="dot"/>}</button><button className="icon-button" onClick={()=>setPage('settings')} aria-label="设置"><Settings2 size={18}/></button></div></header>
   <main>
    <div className="page-heading"><div><div className="eyebrow">{page==='tasks'?'RESEARCH WORKSPACE':page==='results'?'EVIDENCE & EVALUATION':'FUNDAMENTAL RESEARCH'}</div><h1>{pageCopy[page][0]}</h1><p>{pageCopy[page][1]}</p></div><div className="heading-actions">{page==='tasks'?<><button className="button" onClick={()=>setModal('help')}><BookOpen size={16}/> 研究指南</button><button className="button primary" onClick={()=>{setEditingTask(false);setModal('task')}}><Plus size={17}/> 新建研究</button></>:page==='library'?<button className="button primary" onClick={()=>{setNewDoc({title:'',url:'',publisher:'',published_date:'',version_date:'',evidence_note:'',text:'',verified:false});setModal('document')}}><Plus size={17}/> 添加资料</button>:page==='settings'?<button className="button primary" onClick={()=>setModal('profile')}><Plus size={17}/> 添加模型</button>:task?<button className="button" onClick={()=>window.open(`/api/tasks/${activeId}/export?format=markdown`)}><ArrowDownToLine size={16}/> 导出报告</button>:null}</div></div>
    {notice&&<div className={'notice '+(notice.error?'error':'success')} role="alert">{notice.error?<AlertCircle size={18}/>:<CheckCircle2 size={18}/>}<span>{notice.text}</span><button className="icon-button" onClick={()=>setNotice(null)} aria-label="关闭提示"><X size={16}/></button></div>}

    {page==='tasks'&&<>
     <section className="hero"><div><div className="hero-label"><span/> 假设 · 辩论 · 验证</div><h2>把投资逻辑，变成可以检验的因子。</h2><p>价值与成长独立思考，在批判中修正，<br/>在统一的实验标准下寻找可信的证据。</p><div className="hero-tags"><span>沪深非金融 A 股</span><span>3 个月预测期</span><span>月度调仓</span></div></div><div className="hero-diagram"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="orb value-orb"><Leaf size={24}/><span>价值 / 质量</span></div><div className="orb growth-orb"><TrendingUp size={24}/><span>成长 / 动量</span></div><div className="orb central-orb"><FlaskConical size={28}/><span>证据验证</span></div><span className="diagram-caption">独立视角，相互求证</span></div></section>
     <div className="stat-grid">{[{label:'研究任务',value:overview.tasks||0,icon:FlaskConical,note:'每一轮探索，都有完整记录'},{label:'等待你的决策',value:overview.awaiting||0,icon:Clock3,note:'只在关键节点参与判断',accent:true},{label:'已登记实验',value:overview.experiments||0,icon:BarChart3,note:'包含基线、变体与失败记录'},{label:'观察中的因子',value:overview.factors||0,icon:Layers3,note:'保留发现，持续检验'}].map(({label,value,icon:Icon,note,accent})=><div className={'stat-card '+(accent?'accent':'')} key={label}><div><span>{label}</span><Icon size={18}/></div><strong>{value}<small> {label==='观察中的因子'?'个':'项'}</small></strong><p>{note}</p></div>)}</div>
     <section className="panel"><div className="section-head"><div><h2>研究任务 <span className="count">{tasks.length}</span></h2><p>从这里开始，或继续上一次的研究。</p></div><div className="filters"><button className={!filter?'selected':''} onClick={()=>setFilter('')}>全部</button><button className={filter==='待审核'?'selected':''} onClick={()=>setFilter('待审核')}>待决策</button><button className={filter==='完成'?'selected':''} onClick={()=>setFilter('完成')}>已完成</button></div></div>
      {!tasks.length?<Empty title="你的第一轮研究，从一个问题开始" text="创建研究任务后，两位研究员将独立提出假设。你可以先使用演示模式，熟悉完整流程。" action={<button className="button primary" onClick={()=>{setEditingTask(false);setModal('task')}}><Plus size={16}/> 创建第一轮研究</button>}/>:<div className="task-list">{tasks.filter(t=>!filter||(filter==='待审核'?t.gate:t.status==='completed')).map(t=><button key={t.id} className={'task-row '+(activeId===t.id?'selected':'')} onClick={()=>setActiveId(t.id)}><span className="task-symbol"><FlaskConical size={20}/></span><div className="task-main"><strong>{t.name}</strong><span>{t.config.mode==='demo'?'演示研究 · 合成数据':'真实研究'} <i>·</i> {t.config.architecture==='debate'?'双 Agent 辩论':t.config.architecture==='single'?'单 Agent':'双 Agent 独立'}</span></div><Pill tone={t.gate?'amber':t.status==='completed'?'green':t.status==='needs_attention'?'red':'neutral'}>{t.paused?'已请求暂停':statuses[t.status]||t.status}{t.gate?` · 环节 ${t.gate}`:''}</Pill><span className="task-date">{date(t.updated_at)}</span><ChevronRight size={16}/></button>)}</div>}
     </section>
     {task&&<section className="panel task-detail"><div className="section-head"><div><h2>{task.name}</h2><p>任务编号 {task.id.slice(0,8)} · 当前版本 {task.version}</p></div><div className="inline-actions">{task.paused||task.status==='needs_attention'?<button className="button" disabled={busy} onClick={()=>perform(()=>post(`/tasks/${activeId}/resume`),'已请求继续处理')}><Play size={15}/> 继续</button>:running?<button className="button" disabled={busy} onClick={()=>perform(()=>post(`/tasks/${activeId}/pause`),'当前步骤完成后会暂停')}><Pause size={15}/> 暂停</button>:null}<button className="button" onClick={()=>setPage('debate')}>查看过程 <ArrowRight size={15}/></button></div></div>
      {isDemo&&<div className="demo-banner"><FlaskConical size={17}/><div><strong>演示模式</strong> · {activeDataset?.stocks||40} 家模拟公司，合成行情与财报，Agent 为内置脚本。所有结果仅用于验证软件流程。</div></div>}
      <div className="workflow-strip">{[{n:'01',title:'确定研究任务',sub:'你定义方向'},{n:'02',title:'提案与辩论',sub:'不同视角交叉检验'},{n:'05',title:'批准实验批次',sub:'你决定值得验证什么'},{n:'06',title:'代码与回测',sub:'统一标准评估'},{n:'10',title:'最终审核',sub:'你决定保留或淘汰'}].map((s,i)=><div className={(String(task.gate).padStart(2,'0')===s.n?'current':'')} key={s.n}><span className="step-number">{s.n}</span><strong>{s.title}</strong><small>{s.sub}</small>{i<4&&<ChevronRight size={15}/>}</div>)}</div>
      {task.error&&<div className="notice error"><AlertCircle size={18}/><span>{task.error}</span></div>}
      {task.gate&&!task.paused&&<div className="approval-box"><span className="approval-icon"><Clock3 size={23}/></span><div><h3>{task.gate===1?'研究准备好了，等待你确认方向':task.gate===5?'候选假设已形成，等待你批准实验':'结果已整理，等待你的最终判断'}</h3><p>{task.gate===1?`研究范围、时间分区和预算将随本批任务冻结。本批模型预算 ${money(task.config.budget_cny)}。`:task.gate===5?`请检查 ${leafHypotheses.length} 个候选的经济逻辑与争议，批准后最多运行 ${task.config.max_experiments} 个实验版本。`:'最终报告与开发记录分别保存。你可以选择观察、人工保留或淘汰整批候选。'}</p></div><button className="button primary" onClick={()=>openDecision(task.gate===10?'observe':'approve')}>{task.gate===10?'查看并决策':'审核研究'}<ArrowRight size={16}/></button></div>}
      <div className="detail-bottom"><span><Database size={15}/>{activeDataset?.source||task.config.dataset_id}</span><span><Wallet size={15}/> 已用 {money(task.spent)} / {money(task.config.budget_cny)}</span><button className="text-button" onClick={()=>setPage('results')}>实验记录 <ArrowUpRight size={14}/></button></div>
     </section>}
     <div className="two-columns"><section className="panel compact"><div className="section-head"><h2>研究边界</h2><ShieldCheck size={18}/></div><div className="rule-item"><CheckCircle2 size={17}/><div><strong>用当时可知的信息</strong><p>财报按实际披露时间与版本进入回测。</p></div></div><div className="rule-item"><CheckCircle2 size={17}/><div><strong>为最后的检验保留独立数据</strong><p>2023—2025 年结果不进入 Agent 的改写记忆。</p></div></div><div className="rule-item"><CheckCircle2 size={17}/><div><strong>记录失败，也记录发现</strong><p>不因回测不好而删除实验或改变标准。</p></div></div></section><section className="panel compact"><div className="section-head"><h2>最近动态</h2><Activity size={18}/></div>{overview.recent_events?.length?<div className="event-list">{overview.recent_events.slice(0,4).map((e:Row)=><div key={e.id}><i/><p>{e.message}<small>{date(e.created_at)}</small></p></div>)}</div>:<div className="quiet-state"><Clock3 size={25}/><p>研究开始后，这里会记录每一步进展。</p></div>}</section></div>
    </>}

    {['debate','results'].includes(page)&&<div className="task-selector"><span>当前研究</span><select value={activeId} onChange={e=>{setActiveId(e.target.value);setSelectedExperiment('')}}><option value="">选择研究任务</option>{tasks.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select>{selectedTask&&<Pill tone={selectedTask.config.mode==='demo'?'amber':'green'}>{selectedTask.config.mode==='demo'?'演示 · 合成数据':'真实研究'}</Pill>}</div>}

    {page==='debate'&&(!task?<section className="panel"><Empty icon={MessageSquareText} title="先选择一轮研究" text="每个提案、批判和修改都将保留版本，可以从这里追溯。"/></section>:<>
     <ResearchProgress summary={researchSummary} hypotheses={hypotheses}/>
     <div className="agent-grid">{[{role:'value',icon:Leaf,color:'green',desc:'关注估值、现金流与经营质量'},{role:'growth',icon:TrendingUp,color:'blue',desc:'关注经营改善、变化与加速度'},{role:'engineer',icon:Workflow,color:'violet',desc:'让精确的假设成为可计算的公式'}].map(({role,icon:Icon,color,desc})=><div className={'agent-card '+color} key={role}><span><Icon size={22}/></span><div><h3>{roles[role]}</h3><p>{desc}</p><small>{outputs.filter((o:Row)=>o.role===role).length} 条研究记录</small></div></div>)}</div>
     <section className="panel"><div className="section-head"><div><h2>候选假设与版本 <span className="count">{hypotheses.length}</span></h2><p>每次修改保留父版本；相同公式在同一批次内只计算一次。</p></div>{task.gate===5&&<button className="button primary" onClick={()=>openDecision()}>审核实验批次 <ArrowRight size={15}/></button>}</div>{!hypotheses.length?<Empty icon={GitBranch} title="提案尚未开始" text="确认环节 1 后，两位研究员开始独立提案。"/>:<div className="hypothesis-grid">{leafHypotheses.map((h:Row)=><article className="hypothesis-card" key={h.id}><div className="card-meta"><Pill tone={h.role==='value'?'green':'blue'}>{roles[h.role]}</Pill><small>{h.stage.split(':')[0]==='proposal'?'初始提案':'迭代版本'}</small></div><h3>{h.payload.title}</h3><p>{h.payload.mechanism}</p><div className="hypothesis-risk"><strong>什么情况下可能失效</strong><span>{h.payload.failure_condition}</span></div><details><summary>计算定义与修改理由 <ChevronDown size={14}/></summary><code>{h.payload.formula}</code><p>{h.payload.change_reason}</p><small>版本 {h.id.slice(0,8)}{h.parent_id?` ← ${h.parent_id.slice(0,8)}`:''} · 证据来源 {h.payload.evidence_ids.length} 项</small></details></article>)}</div>}</section>
     <section className="panel"><div className="section-head"><div><h2>辩论记录</h2><p>{isDemo?'当前为固定脚本演示，未调用云端模型。实证批判和回应见上方谱系。':'原始模型输出与提示词版本均已归档。'}</p></div><Pill>{outputs.length} 条记录</Pill></div><div className="conversation">{outputs.map((o:Row)=><article key={o.id} className={'message '+o.role}><div className="message-avatar">{o.role==='value'?<Leaf size={17}/>:o.role==='growth'?<TrendingUp size={17}/>:<Workflow size={17}/>}</div><div className="message-body"><div className="message-head"><strong>{roles[o.role]}</strong><Pill>{o.payload.action}</Pill><time>{date(o.created_at)}</time></div><p>{o.payload.output.explanation}</p>{o.payload.output.critiques.map((c:Row,i:number)=><div className="critique" key={i}><strong>{titleFor(c.target_id)}</strong><p>{c.issue}</p><span>建议检验：{c.proposed_test}</span></div>)}{o.payload.output.hypotheses.map((h:Row,i:number)=><details className="message-hypothesis" key={i}><summary>{h.title}<ChevronDown size={14}/></summary><p>{h.mechanism}</p><code>{h.formula}</code><p>{h.change_reason}</p></details>)}<small className="message-model">{o.payload.model} · {o.payload.prompt_version}</small></div></article>)}</div>{!outputs.length&&<div className="quiet-state">研究开始后，独立提案和交叉批判会显示在这里。</div>}</section>
    </>)}

    {page==='results'&&(!task?<section className="panel"><Empty icon={BarChart3} title="选择一轮研究，查看证据" text="开发、验证与最终测试分开显示，不把分组收益当作可执行策略收益。"/></section>:<>
     <ResearchFeedback summary={researchSummary} hypotheses={hypotheses}/>
     {isDemo&&<div className="demo-banner"><FlaskConical size={17}/><span><strong>软件验收演示</strong> · 下列结果来自合成数据，不能用于评价真实投资价值。</span></div>}
     {task.final_status==='previously_used'&&<div className="notice error"><ShieldCheck size={18}/><span>本批与已使用的最终测试区重叠，未重复开封；候选需要新数据观察。</span></div>}
     <div className="results-toolbar"><div className="segmented">{[['development','开发区 · 2014–2019'],['validation','验证区 · 2020–2022'],['final','最终测试 · 2023–2025'],['recent','近期补充'],['forward','前瞻观察']].map(([id,label])=><button key={id} className={split===id?'active':''} onClick={()=>{setSplit(id);setSelectedExperiment('')}}>{label}</button>)}</div><select value={selected?.id||''} onChange={e=>setSelectedExperiment(e.target.value)}><option value="">选择实验</option>{matchingExperiments.map(e=><option key={e.id} value={e.id}>{titleFor(e.hypothesis_id)} · {e.status==='complete'?'完成':'失败'} · {e.id.slice(0,5)}</option>)}</select></div>
     {!selected?<section className="panel"><Empty icon={BarChart3} title={split==='final'?'最终测试尚未开放':'这里还没有实验结果'} text={split==='final'?'候选冻结后，由受控评估程序统一执行，结果不会回传研究 Agent。':'批准第 5 环节后开始代码验证。失败实验也会在这里保留。'}/></section>:selected.status==='failed'?<section className="panel"><Empty icon={AlertCircle} title="这次实验未能形成有效结果" text={report.error}/><div className="formula-box"><code>{report.formula}</code></div></section>:<>
      {report.short_observation&&<div className="information-banner"><Clock3 size={18}/><span>当前不足 12 个月，仅作描述性观察；不报告统计显著性，不能作为独立验证结论。</span></div>}<div className="report-heading"><h2>{titleFor(selected.hypothesis_id)}</h2><span>{report.signals} 个月度截面 · 字段覆盖 {pct(report.coverage)} · {stageName[split]}</span></div>
      <div className="stat-grid report-stats">{[{label:'60 日排名相关性',value:num(report.ic?.['60']?.mean),note:'因子排名与后续收益排名的关系'},{label:'组合年化收益',value:pct(report.portfolio.annual_return),note:'包含交易成本与成交限制'},{label:'相对基准年化差',value:pct(report.annual_excess),note:'基准为同股票池等权组合'},{label:'最大回撤',value:pct(report.portfolio.max_drawdown),note:'净值从历史高点回落的最大幅度'}].map(s=><div className="stat-card" key={s.label}><div><span>{s.label}</span></div><strong className="metric">{s.value}</strong><p>{s.note}</p></div>)}</div>
      <section className="panel"><div className="section-head"><div><h2>组合净值</h2><p>月度调仓，次一交易日执行；曲线按月展示。</p></div><div className="chart-legend"><span><i/> 因子组合</span><span><i className="gray"/> 同池等权基准</span></div></div><div className="chart"><ResponsiveContainer width="100%" height={280}><AreaChart data={report.portfolio.curve.map((r:Row,i:number)=>({...r,benchmark:report.benchmark.curve[i]?.nav}))}><defs><linearGradient id="navFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#2c735b" stopOpacity={.18}/><stop offset="100%" stopColor="#2c735b" stopOpacity={0}/></linearGradient></defs><CartesianGrid vertical={false} stroke="#eceeea"/><XAxis dataKey="date" tickFormatter={v=>v.slice(0,7)} minTickGap={60} tickLine={false} axisLine={false} tick={{fontSize:11,fill:'#89908a'}}/><YAxis tickLine={false} axisLine={false} tick={{fontSize:11,fill:'#89908a'}} domain={['auto','auto']} tickFormatter={v=>v.toFixed(2)}/><Tooltip formatter={(v:any)=>Number(v).toFixed(3)}/><Area name="因子组合" dataKey="nav" stroke="#2d775b" fill="url(#navFill)" strokeWidth={2} isAnimationActive={false}/><Area name="同池基准" dataKey="benchmark" stroke="#a7aeaa" fill="none" strokeWidth={1.5} isAnimationActive={false}/></AreaChart></ResponsiveContainer></div></section>
      <div className="two-columns"><section className="panel"><div className="section-head"><div><h2>排序预测力</h2><p>按收益重叠长度调整统计检验。</p></div><div className="filters">{['20','60','120'].map(h=><button key={h} className={horizon===h?'selected':''} onClick={()=>setHorizon(h)}>{h} 日</button>)}</div></div><div className="chart small"><ResponsiveContainer width="100%" height={200}><LineChart data={report.ic?.[horizon]?.points||[]}><CartesianGrid vertical={false} stroke="#eceeea"/><XAxis dataKey="date" tickFormatter={v=>v.slice(2,7)} minTickGap={55} tickLine={false} axisLine={false} tick={{fontSize:10}}/><YAxis width={38} tickLine={false} axisLine={false} tick={{fontSize:10}}/><ReferenceLine y={0} stroke="#acb5ae" strokeDasharray="3 3"/><Tooltip/><Line type="monotone" dataKey="ic" name="Rank IC" stroke="#2d775b" dot={false} isAnimationActive={false}/></LineChart></ResponsiveContainer></div><div className="chart-foot">多次试验校正后 p 值：{num(report.ic?.[horizon]?.p_adjusted)} <span>收益标签覆盖 {pct(report.ic?.[horizon]?.label_coverage)} · 缺失 {report.ic?.[horizon]?.missing_labels||0} 条</span></div></section><section className="panel"><div className="section-head"><div><h2>五组前瞻收益</h2><p>从低分到高分；用于诊断，不等同于策略收益。</p></div></div><div className="chart small"><ResponsiveContainer width="100%" height={200}><BarChart data={report.groups}><CartesianGrid vertical={false} stroke="#eceeea"/><XAxis dataKey="group" tickFormatter={v=>`第 ${v} 组`} tickLine={false} axisLine={false} tick={{fontSize:11}}/><YAxis width={45} tickFormatter={v=>pct(v,0)} tickLine={false} axisLine={false} tick={{fontSize:10}}/><ReferenceLine y={0} stroke="#acb5ae"/><Tooltip formatter={(v:any)=>pct(v,2)}/><Bar dataKey="mean_forward_return" name="平均 60 日收益" fill="#83a58d" radius={[4,4,0,0]} maxBarSize={43} isAnimationActive={false}/></BarChart></ResponsiveContainer></div><div className="chart-foot">相邻月份的 60 日收益存在重叠，不是独立观测。</div></section></div>
      <div className="two-columns"><section className="panel"><div className="section-head"><h2>稳健性与执行约束</h2></div><table><thead><tr><th>情景</th><th>年化收益</th><th>最大回撤</th></tr></thead><tbody>{[['月度调仓',report.portfolio],['双倍交易成本',report.double_cost],['季度调仓',report.quarterly]].map(([label,r]:any)=><tr key={label}><td>{label}</td><td>{pct(r.annual_return)}</td><td>{pct(r.max_drawdown)}</td></tr>)}</tbody></table><div className="chart-foot">受成交限制影响的指令 {report.portfolio.blocked_orders} 次 · 年换手 {num(report.portfolio.annual_turnover,1)} 倍</div></section><section className="panel"><div className="section-head"><h2>行业内表现</h2></div><table><thead><tr><th>行业</th><th>平均排名相关性</th><th>有效月份</th></tr></thead><tbody>{report.industries.map((r:Row)=><tr key={r.name}><td>{r.name}</td><td>{num(r.rank_ic)}</td><td>{r.months}</td></tr>)}</tbody></table></section></div>
      <section className="panel"><div className="section-head"><div><h2>与已有因子的关系</h2><p>检查是否重复已有信号，并剔除行业、规模与三个基础因子的线性影响。</p></div></div><div className="table-scroll"><table><thead><tr><th>基础因子</th><th>排名相关性</th><th>有效月份</th></tr></thead><tbody>{report.baseline_comparison?.map((r:Row)=><tr key={r.name}><td>{r.name}</td><td>{num(r.rank_correlation)}</td><td>{r.months}</td></tr>)}</tbody></table></div><div className="chart-foot">剔除基础暴露后的 60 日相关性：{num(report.controlled_ic?.mean)} · 有效月份 {report.controlled_ic?.n||0}（诊断性指标）</div></section>
      <details className="panel technical"><summary>计算定义、代码与方法边界 <ChevronDown size={16}/></summary><pre>{report.source_code}</pre>{report.limitations.map((x:string)=><p key={x}>· {x}</p>)}<small>引擎 {report.engine_version} · 数据版本 {report.dataset_version.slice(0,12)}</small></details>
     </>}
     <section className="panel"><div className="section-head"><div><h2>全部实验档案 <span className="count">{experiments.length}</span></h2><p>基线、变体和失败记录均保留，点击一行查看详情。</p></div><button className="button" onClick={()=>window.open(`/api/tasks/${activeId}/export`)}><ArrowDownToLine size={15}/> 完整档案</button></div><div className="table-scroll"><table className="clickable-table"><thead><tr><th>因子 / 实验版本</th><th>数据区间</th><th>状态</th><th>60 日排名相关性</th><th>年化收益</th><th>最大回撤</th></tr></thead><tbody>{experiments.map(e=><tr key={e.id} onClick={()=>{setSplit(e.split);setSelectedExperiment(e.id);window.scrollTo({top:0,behavior:'smooth'})}}><td><strong>{titleFor(e.hypothesis_id)}</strong><small>{e.id.slice(0,8)}</small></td><td>{stageName[e.split]}</td><td><Pill tone={e.status==='complete'?'green':'red'}>{e.status==='complete'?'已完成':'未通过'}</Pill></td><td>{num(e.payload.ic?.['60']?.mean)}</td><td>{pct(e.payload.portfolio?.annual_return)}</td><td>{pct(e.payload.portfolio?.max_drawdown)}</td></tr>)}</tbody></table>{!experiments.length&&<div className="quiet-state">尚无实验记录</div>}</div></section>
     {task.status==='completed'&&<section className="panel"><div className="section-head"><div><h2>冻结之后，继续观察</h2><p>先导入保留原始历史记录的追加数据版本。只评估冻结日期以后的数据，结果只供人工查看。</p></div></div><div className="search-row"><select value={observationDataset} onChange={e=>setObservationDataset(e.target.value)}><option value="">选择追加数据版本</option>{datasets.filter(d=>d.demo===isDemo).map(d=><option key={d.id} value={d.id}>{d.source} · {d.id}</option>)}</select><button className="button" disabled={busy||!observationDataset} onClick={()=>perform(async()=>{await post(`/tasks/${activeId}/observe`,{dataset_id:observationDataset})},'前瞻检查已提交；若尚无新数据，会记录等待原因。')}>检查新数据 <ArrowRight size={15}/></button></div></section>}
     {comparisons.filter(c=>c.groups.some((g:Row)=>g.task_id===activeId)).map(c=><section className="panel" key={c.id}><div className="section-head"><h2>相同上限下的研究对照</h2></div><p className="subtle">{c.note}</p><div className="table-scroll"><table><thead><tr><th>方式</th><th>候选版本</th><th>失败实验</th><th>验证 IC 均值</th><th>模型调用</th><th>实际费用</th></tr></thead><tbody>{c.groups.map((g:Row)=><tr key={g.task_id}><td>{({single:'单 Agent',independent:'双 Agent 独立',debate:'双 Agent 辩论'} as Row)[g.architecture]}<small>{statuses[g.status]}</small></td><td>{g.versions}</td><td>{g.failed_experiments}</td><td>{num(g.mean_validation_ic)}</td><td>{g.model_calls}</td><td>{money(g.spent_cny)}</td></tr>)}</tbody></table></div></section>)}
     <div className="comparison-cta"><GitBranch size={22}/><div><h3>辩论本身，是否带来更好的研究？</h3><p>创建单 Agent、双 Agent 独立与双 Agent 辩论三组任务，使用相同预算和实验上限。</p></div><button className="button" disabled={busy} onClick={()=>perform(async()=>{await post(`/tasks/${activeId}/comparison`);setPage('tasks')},'三组对照任务已创建，分别等待环节 1 确认。')}>创建对照研究 <ArrowUpRight size={15}/></button></div>
    </>)}

    {page==='library'&&<>
     <div className="information-banner"><ShieldCheck size={19}/><div><strong>研究资料截止于 2022 年 12 月 31 日</strong><p>只有已核验原文、发表日期和具体版本的资料，才能进入研究 Agent 的上下文。</p></div><Pill tone="green">时间边界已启用</Pill></div>
     <section className="panel"><div className="section-head"><div><h2>发现研究来源</h2><p>检索结果用于寻找原文，不会自动成为已验证证据。</p></div><Pill tone={providers.tavily_configured?'green':'neutral'}>{providers.tavily_configured?'Tavily 已配置':'检索凭据待配置'}</Pill></div><div className="search-row"><Search size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="输入研究主题，例如现金流质量、盈利加速度"/><button className="button primary" disabled={busy} onClick={()=>perform(async()=>setSearchResults(await post('/documents/search',{query,cutoff:'2022-12-31'})))}>{busy?<Loader2 className="spin" size={16}/>:<Search size={16}/>} 检索来源</button></div>{searchResults.length>0&&<div className="source-results">{searchResults.map((r:Row,i:number)=><article key={i}><div><h3><a href={r.url} target="_blank" rel="noreferrer">{r.title}<ArrowUpRight size={13}/></a></h3><p>{r.snippet}</p><small>检索日期线索：{r.published_date||'未知'} · 需要核验原文版本</small></div><button className="button" onClick={()=>{setNewDoc({...newDoc,title:r.title,url:r.url,verified:false});setModal('document')}}>添加并核验</button></article>)}</div>}</section>
     <section className="panel"><div className="section-head"><div><h2>已保存资料 <span className="count">{docs.length}</span></h2><p>包括尚待核验和因日期超限而被隔离的资料。</p></div></div>{!docs.length?<Empty icon={BookOpen} title="建立你的第一份研究证据" text="可以检索来源，或添加作者、期刊与研报发布机构的原文链接。" action={<button className="button" onClick={()=>setModal('document')}><Plus size={16}/> 添加原文链接</button>}/>:<div className="document-grid">{docs.map(d=><article className="document-card" key={d.id}><div className="document-icon"><FileText size={24}/></div><div className="card-meta"><Pill tone={!d.verified?'amber':d.version_date>'2022-12-31'?'red':'green'}>{!d.verified?'待核验':d.version_date>'2022-12-31'?'日期超限 · 已隔离':'研究可用'}</Pill><small>{d.publisher}</small></div><h3>{d.title}</h3><p>发表 {d.published_date}<br/>当前版本 {d.version_date}</p><div><a className="text-button" href={d.url} target="_blank" rel="noreferrer">查看原文 <ArrowUpRight size={14}/></a><button className="text-button" onClick={()=>perform(async()=>{const full=await api('/documents/'+d.id);setNewDoc(full);setModal('document')})}>核验资料</button><small>{Math.round(d.text_length/1000)}k 字符</small></div></article>)}</div>}</section>
    </>}

    {page==='factors'&&<section className="panel"><div className="section-head"><div><h2>你的因子档案</h2><p>人工保留代表继续研究的决定，不能代替真实市场检验。</p></div><Pill>{factors.length} 个版本</Pill></div>{!factors.length?<Empty icon={Layers3} title="让通过审视的想法，在这里积累" text="完成环节 10 后，候选会带着公式、研究来源和你的决定进入档案。"/>:<div className="hypothesis-grid">{factors.map(f=><article className="hypothesis-card" key={f.id}><div className="card-meta"><Pill tone={f.status==='rejected'?'red':f.status==='retained'?'green':'amber'}>{f.status==='rejected'?'已淘汰':f.status==='retained'?'人工保留':'持续观察'}</Pill>{f.config.mode==='demo'&&<Pill tone="amber">演示数据</Pill>}</div><h3>{f.payload.title}</h3><p>{f.payload.mechanism}</p><div className="hypothesis-risk"><strong>审核理由</strong><span>{f.reason||'未补充说明'}</span></div><button className="text-button" onClick={()=>{setActiveId(f.task_id);setPage('results')}}>查看研究档案 <ArrowUpRight size={14}/></button></article>)}</div>}</section>}

    {page==='settings'&&<>
     <section className="panel"><div className="section-head"><div><h2>数据来源与试样</h2><p>连接成功不代表数据已合格；试样与正式数据验收分开记录。</p></div><button className="button" onClick={()=>setModal('import')}><Database size={16}/> 导入已整理数据</button></div><div className="provider-grid">{providers.providers?.map((p:Row)=><article className="provider-card" key={p.id}><div className="card-meta"><span className="provider-logo">{p.id==='ricequant'?'RQ':'TS'}</span><Pill tone={p.configured?'green':'neutral'}>{p.configured?'凭据已配置':'待配置凭据'}</Pill></div><h3>{p.name}</h3><p>{p.description}</p><small>{p.pricing}</small><div className="provider-actions"><a href={p.docs} target="_blank" rel="noreferrer">接口说明 <ArrowUpRight size={13}/></a><button className="button" onClick={()=>{setSampleProvider(p.id);setSampleSymbols(p.id==='ricequant'?'000001.XSHE':'000001.SZ');setModal('sample')}}>试取样本 <ArrowRight size={14}/></button></div></article>)}</div><div className="settings-note"><ShieldCheck size={16}/><span>密钥由本机凭据工具保存，网页只显示是否配置。<button className="text-button" onClick={()=>setModal('secrets')}>查看设置方法</button></span></div></section>
     <section className="panel"><div className="section-head"><div><h2>可用数据集</h2><p>每个数据集拥有内容指纹，更新数据时使用新的版本编号。</p></div></div><div className="table-scroll"><table><thead><tr><th>数据集</th><th>股票数量</th><th>行情覆盖</th><th>历史修订</th><th>状态</th></tr></thead><tbody>{datasets.map(d=><tr key={d.id}><td><strong>{d.source}</strong><small>{d.id} · {d.version.slice(0,10)}</small></td><td>{d.stocks}</td><td>{d.market_start} — {d.market_end}</td><td>{d.revisions} 条</td><td><Pill tone={d.demo?'amber':d.pit_verified?'green':'neutral'}>{d.demo?'合成演示':d.pit_verified?'已确认时点口径':'待核验'}</Pill></td></tr>)}</tbody></table></div></section>
     <section className="panel"><div className="section-head"><div><h2>候选模型</h2><p>先用相同任务比较质量与费用，再选择研究模型。</p></div><button className="button" onClick={()=>setModal('benchmark')}><Target size={16}/> 发起模型试评</button></div>{!profiles.length?<Empty icon={Sparkles} title="为研究员配置云端模型" text="填写接口地址、模型名称和计费信息；密钥单独保存在本机系统凭据中。" action={<button className="button" onClick={()=>setModal('profile')}><Plus size={16}/> 添加候选模型</button>}/>:<div className="model-grid">{profiles.map(p=><article className="model-card" key={p.id}><div className="card-meta"><span className="model-icon"><Sparkles size={21}/></span><Pill tone={p.configured?'green':'amber'}>{p.configured?'已配置凭据':'密钥待设置'}</Pill></div><h3>{p.payload.name}</h3><p>{p.payload.model}</p><div className="model-pricing"><span>输入 / 百万 token <strong>{money(p.payload.input_cny_per_million)}</strong></span><span>输出 / 百万 token <strong>{money(p.payload.output_cny_per_million)}</strong></span></div><small>凭据名称：{p.payload.secret_name}</small></article>)}</div>}</section>
     <section className="panel"><div className="section-head"><div><h2>试样与试评记录</h2><p>试样不会自动进入正式研究，模型试评不承诺盈利能力。</p></div></div>{jobs.filter(j=>j.kind!=='research'&&['queued','running','failed'].includes(j.status)).map(j=><div className="job-row" key={j.id}>{j.status==='failed'?<AlertCircle size={17}/>:<Loader2 size={17} className="spin"/>}<span>{j.kind==='data_sample'?'数据试样':'模型试评'} · {j.status==='failed'?j.error:'正在处理'}</span></div>)}{benchmarks.length?benchmarks.map(b=><details className="benchmark-result" key={b.id}><summary><strong>{b.payload.type==='model_benchmark'?'模型试评':b.payload.provider+' 数据试样'}</strong><span>{date(b.created_at)} <ChevronDown size={15}/></span></summary>{b.payload.results?b.payload.results.map((r:Row)=><div className="benchmark-model" key={r.profile_id}><h3>{r.name} · {r.auto_checks_passed}/3 项自动检查通过</h3><p>费用 {money(r.cost_cny)} · 用时 {r.elapsed_seconds} 秒</p><small>{r.note}</small>{r.cases.map((c:Row)=><details key={c.case}><summary>任务 {c.case} · {c.passed?'通过':'未通过'}</summary><pre>{JSON.stringify(c.output||c.error,null,2)}</pre></details>)}</div>):<><p>历史时点尚未核验，需要与原始公告核对。</p>{b.payload.tables?.map((t:Row)=><div key={t.name}><strong>{t.name}</strong><p>{t.rows} 行 · {t.columns.join('、')}</p></div>)}</>}</details>):<div className="quiet-state">配置凭据后，可以开始小规模试样和模型对照。</div>}</section>
    </>}
    <footer className="page-footer"><span>FUNDAMENTAL LAB <i>·</i> 让研究可追溯，让结论有依据。</span><span>本机保存 · 版本 0.1</span></footer>
   </main>
  </div>

  {modal==='task'&&<Modal title={editingTask?'修改研究设置':'新建一轮研究'} subtitle="先明确想验证的问题，再让研究员展开工作。" onClose={()=>setModal('')} wide><form onSubmit={e=>{e.preventDefault();create()}}><div className="modal-content"><div className="mode-picker">{[['demo','演示模式','合成数据与脚本，不消耗 API 费用'],['live','真实研究','使用已验收的数据和云端模型']].map(([id,label,sub])=><button type="button" key={id} className={newTask.mode===id?'chosen':''} onClick={()=>setNewTask({...newTask,mode:id,dataset_id:datasets.find(d=>id==='demo'?d.demo:!d.demo)?.id||'',budget_cny:id==='demo'?0:20})}><span>{newTask.mode===id?<CheckCircle2 size={18}/>:<span className="radio"/>}<strong>{label}</strong></span><small>{sub}</small></button>)}</div><Field label="研究名称"><input required value={newTask.name} onChange={e=>setNewTask({...newTask,name:e.target.value})}/></Field><Field label="你想验证什么"><textarea required rows={3} value={newTask.objective} onChange={e=>setNewTask({...newTask,objective:e.target.value})}/></Field><div className="form-grid"><Field label="数据集"><select value={newTask.dataset_id} onChange={e=>setNewTask({...newTask,dataset_id:e.target.value})}>{datasets.filter(d=>newTask.mode==='demo'?d.demo:!d.demo).map(d=><option value={d.id} key={d.id}>{d.source}</option>)}{newTask.mode==='live'&&!datasets.some(d=>!d.demo)&&<option value="">请先导入正式数据</option>}</select></Field><Field label="研究方式"><select value={newTask.architecture} onChange={e=>setNewTask({...newTask,architecture:e.target.value})}><option value="debate">双 Agent 交叉辩论</option><option value="independent">双 Agent 独立提案（对照）</option><option value="single">单 Agent（对照）</option></select></Field></div>{newTask.mode==='live'&&<div className="form-grid"><Field label="候选模型"><select required value={newTask.model_profile_id||''} onChange={e=>setNewTask({...newTask,model_profile_id:e.target.value})}><option value="">请选择已配置模型</option>{profiles.map(p=><option key={p.id} value={p.id}>{p.payload.name}{p.configured?'':'（凭据未设置）'}</option>)}</select></Field><Field label="本批模型费用上限（人民币）" hint="不是预估账单。发起调用前会预留费用，余额不足时停止。"><input type="number" min="0.01" step="0.01" required value={newTask.budget_cny} onChange={e=>setNewTask({...newTask,budget_cny:Number(e.target.value)})}/></Field></div>}<div className="form-summary"><div><ShieldCheck size={16}/><strong>本批默认研究规则</strong></div><p>沪深非金融 A 股 · 60 日主要预测目标 · 月度调仓</p><p>2014–2019 开发 / 2020–2022 验证 / 2023–2025 最终测试</p><p>最多 2 轮前置辩论、2 轮交替实证改写、20 个实验定义；你参与 1、5、10 环节。</p></div><ResearchRules policy={newTask.research_policy} onChange={p=>setNewTask({...newTask,research_policy:p})}/></div><div className="modal-footer"><button type="button" className="button" onClick={()=>setModal('')}>取消</button><button className="button primary" disabled={busy}>{busy?<Loader2 size={16} className="spin"/>:<Plus size={16}/>} {editingTask?'保存研究设置':'创建研究任务'}</button></div></form></Modal>}

  {modal==='decision'&&task&&<Modal title={`环节 ${task.gate} · ${task.gate===1?'确认研究方向':task.gate===5?'审核实验批次':'最终研究判断'}`} subtitle={task.name} onClose={()=>setModal('')} wide><div className="modal-content">{isDemo&&<div className="demo-banner"><FlaskConical size={16}/><span>这是演示研究，不消耗模型费用，结果不构成投资证据。</span></div>}{task.gate===1?<><div className="review-summary"><span>研究目标</span><p>{task.config.objective}</p><span>数据与预算</span><p>{activeDataset?.source} · 预算上限 {money(task.config.budget_cny)}</p><button className="text-button" onClick={()=>{setNewTask({...task.config});setEditingTask(true);setModal('task')}}>修改研究设置 <ArrowUpRight size={15}/></button></div><div className="form-summary">确认后进入数据检查与独立提案，再次需要你参与时将停在环节 5。</div></>:task.gate===5?<><div className="review-summary"><span>本次准备验证</span>{leafHypotheses.map((h:Row)=><div className="review-hypothesis" key={h.id}><strong>{h.payload.title}</strong><p>{h.payload.mechanism}</p><small>主要争议：{h.payload.failure_condition}</small></div>)}</div><div className="form-summary">批准范围包含不超过 2 轮实证改写，总计最多 {task.config.max_experiments} 个实验版本；不改变股票池、时间分区或评分标准。剩余额度 {money(task.config.budget_cny-task.spent)}。</div></>:<div className="review-summary"><span>本批结果</span><p>通过门槛和去重后，冻结 {researchSummary?.candidate_selection?.[0]?.payload?.selected_ids?.length??0} 个定义供本次人工决定；其他版本保留在研究档案。</p><p>已登记 {task.experiments.length} 项开发与验证实验、{task.final_results.filter((r:Row)=>r.split==='final').length} 项最终测试、{task.final_results.filter((r:Row)=>r.split==='recent').length} 项近期补充。</p><p>最终测试状态：{({demo_only:'演示结果',tested:'已完成',previously_used:'区间已使用，等待新数据',no_candidates:'没有合格候选'} as Row)[task.final_status]||task.final_status}</p><button className="text-button" onClick={()=>{setModal('');setPage('results');setSplit('final')}}>先查看完整实验报告 <ArrowUpRight size={15}/></button></div>}{task.gate!==10&&<ResearchRules policy={task.config.research_policy}/>}<Field label="你的决定"><select value={decision.action} onChange={e=>setDecision({...decision,action:e.target.value})}>{task.gate===10?<><option value="observe">纳入观察，等待新数据验证</option><option value="retain">人工保留到因子库</option><option value="reject">淘汰本批候选</option></>:<><option value="approve">批准，继续研究</option><option value="return">退回，补充或修改</option><option value="reject">结束本批研究</option></>}</select></Field><Field label="判断依据或修改要求"><textarea rows={3} value={decision.reason} placeholder="例如：先检查现金流是否来自一次性回款；希望保留与原始增长因子的对照。" onChange={e=>setDecision({...decision,reason:e.target.value})}/></Field></div><div className="modal-footer"><button className="button" onClick={()=>setModal('')}>稍后决定</button><button className="button primary" disabled={busy} onClick={submitDecision}>{busy?<Loader2 className="spin" size={16}/>:<Check size={16}/>}记录决定</button></div></Modal>}

  {modal==='profile'&&<Modal title="添加候选模型" subtitle="输入公开配置，密钥通过本机凭据工具单独保存。" onClose={()=>setModal('')}><form onSubmit={e=>{e.preventDefault();saveProfile()}}><div className="modal-content"><Field label="显示名称"><input required value={newProfile.name} placeholder="例如：候选模型 A" onChange={e=>setNewProfile({...newProfile,name:e.target.value})}/></Field><div className="form-grid"><Field label="接口协议"><select value={newProfile.protocol} onChange={e=>setNewProfile({...newProfile,protocol:e.target.value})}><option value="responses">Responses API</option><option value="chat_completions">Chat Completions 兼容接口</option></select></Field><Field label="模型 ID"><input required value={newProfile.model} placeholder="按供应商文档填写" onChange={e=>setNewProfile({...newProfile,model:e.target.value})}/></Field></div><Field label="接口基础地址"><input type="url" required value={newProfile.base_url} onChange={e=>setNewProfile({...newProfile,base_url:e.target.value})}/></Field><Field label="本机凭据名称" hint="只填名称，不填密钥。例如 research-model。"><input required value={newProfile.secret_name} onChange={e=>setNewProfile({...newProfile,secret_name:e.target.value})}/></Field><div className="form-grid"><Field label="输入价格 / 百万 token（人民币）"><input required type="number" step="0.01" min="0" value={newProfile.input_cny_per_million} onChange={e=>setNewProfile({...newProfile,input_cny_per_million:Number(e.target.value)})}/></Field><Field label="输出价格 / 百万 token（人民币）"><input required type="number" step="0.01" min="0" value={newProfile.output_cny_per_million} onChange={e=>setNewProfile({...newProfile,output_cny_per_million:Number(e.target.value)})}/></Field></div><small>请使用供应商当前报价；若以外币计价，先换算成人民币。模型须支持 JSON Schema 结构化输出。</small></div><div className="modal-footer"><button type="button" className="button" onClick={()=>setModal('')}>取消</button><button className="button primary" disabled={busy}>保存配置</button></div></form></Modal>}

  {modal==='document'&&<Modal title="添加与核验研究资料" subtitle="核验指记录原文事实，不是判断论点一定正确。" onClose={()=>setModal('')} wide><form onSubmit={e=>{e.preventDefault();saveDoc()}}><div className="modal-content"><Field label="资料标题"><input required value={newDoc.title} onChange={e=>setNewDoc({...newDoc,title:e.target.value})}/></Field><Field label="原文链接"><input type="url" required value={newDoc.url} onChange={e=>setNewDoc({...newDoc,url:e.target.value})}/></Field><Field label="作者、期刊或研报发布机构"><input required value={newDoc.publisher} onChange={e=>setNewDoc({...newDoc,publisher:e.target.value})}/></Field><div className="form-grid"><Field label="首次发表日期"><input type="date" required value={newDoc.published_date} onChange={e=>setNewDoc({...newDoc,published_date:e.target.value})}/></Field><Field label="本次原文版本日期"><input type="date" required value={newDoc.version_date} onChange={e=>setNewDoc({...newDoc,version_date:e.target.value})}/></Field></div><Field label="原文版本的核验依据" hint="例如：PDF 封面发布日期、作者页面明确标注的版本日期和对应位置。"><textarea rows={2} value={newDoc.evidence_note} onChange={e=>setNewDoc({...newDoc,evidence_note:e.target.value})}/></Field><details className="optional-field"><summary>提供核对后的正文（可选）</summary><textarea rows={4} placeholder="留空时，系统尝试读取公开 HTML 或可检索 PDF 原文。" value={newDoc.text} onChange={e=>setNewDoc({...newDoc,text:e.target.value})}/></details><label className="check-field"><input type="checkbox" checked={newDoc.verified} onChange={e=>setNewDoc({...newDoc,verified:e.target.checked})}/><span>我已核对原文、发布机构和具体版本，并记录了依据</span></label><small>未核验的资料可以保存，但不会提供给研究 Agent。日期超限的资料始终隔离。</small></div><div className="modal-footer"><button type="button" className="button" onClick={()=>setModal('')}>取消</button><button className="button primary" disabled={busy}>{busy?<Loader2 size={16} className="spin"/>:<Plus size={16}/>}保存资料</button></div></form></Modal>}

  {modal==='import'&&<Modal title="导入标准化数据" subtitle="支持 CSV 或 Parquet。原始供应商表需先对齐字段与口径。" onClose={()=>setModal('')}><form onSubmit={e=>{e.preventDefault();perform(async()=>{if(!financialFile||!marketFile)throw new Error('请选择财报和行情文件');const form=new FormData();form.append('dataset_id',importForm.dataset_id);form.append('source',importForm.source);form.append('pit_verified',String(importForm.pit_verified));form.append('financials',financialFile);form.append('market',marketFile);await api('/datasets/import',{method:'POST',body:form});setModal('')},'数据集已登记；任务开始前会再次检查覆盖。')}}><div className="modal-content"><Field label="数据集编号"><input required pattern="[a-zA-Z0-9_.-]+" placeholder="例如 ashare-2026-v1" value={importForm.dataset_id} onChange={e=>setImportForm({...importForm,dataset_id:e.target.value})}/></Field><Field label="来源与版本说明"><input required value={importForm.source} onChange={e=>setImportForm({...importForm,source:e.target.value})}/></Field><Field label="财报版本表"><input type="file" required accept=".csv,.parquet" onChange={e=>setFinancialFile(e.target.files?.[0]||null)}/></Field><Field label="历史行情与交易状态表"><input type="file" required accept=".csv,.parquet" onChange={e=>setMarketFile(e.target.files?.[0]||null)}/></Field><label className="check-field"><input type="checkbox" checked={importForm.pit_verified} onChange={e=>setImportForm({...importForm,pit_verified:e.target.checked})}/><span>已按原始公告抽样验收披露日期、修订版本和累计口径</span></label><small>字段规范与导入示例见项目使用说明。未经时点验收的数据不会用于真实研究。</small></div><div className="modal-footer"><button type="button" className="button" onClick={()=>setModal('')}>取消</button><button className="button primary" disabled={busy}>导入并检查</button></div></form></Modal>}
  {modal==='sample'&&<Modal title="试取少量数据" subtitle="只检查连接与样本，不自动标记为已验收。" onClose={()=>setModal('')}><div className="modal-content"><Field label="股票代码（最多 3 个，以逗号分隔）"><input value={sampleSymbols} onChange={e=>setSampleSymbols(e.target.value)}/></Field><p className="subtle">默认查询 2020—2022 年财务样本。供应商可能按其账户规则消耗额度。</p></div><div className="modal-footer"><button className="button" onClick={()=>setModal('')}>取消</button><button className="button primary" disabled={busy} onClick={()=>perform(async()=>{await post(`/providers/${sampleProvider}/sample`,{symbols:sampleSymbols.split(/[,，]/).map(s=>s.trim()).filter(Boolean),start:'2020-01-01',end:'2022-12-31'});setModal('')},'试样已提交到后台，结果将在设置页显示。')}>开始试样</button></div></Modal>}
  {modal==='benchmark'&&<Modal title="比较候选模型" subtitle="每个模型接受相同的提案、批判和公式实现任务。" onClose={()=>setModal('')}><div className="modal-content">{profiles.map(p=><label className="check-field" key={p.id}><input type="checkbox" checked={benchmarkSelection.includes(p.id)} onChange={e=>setBenchmarkSelection(e.target.checked?[...benchmarkSelection,p.id]:benchmarkSelection.filter(id=>id!==p.id))}/><span>{p.payload.name} · {p.payload.model}</span></label>)}{!profiles.length&&<p>请先添加并配置至少一个候选模型。</p>}<Field label="本次试评总预算（人民币）" hint="总额在所选模型之间均分；发起后会调用真实 API。"><input type="number" min="0.01" step="0.01" value={benchmarkBudget} onChange={e=>setBenchmarkBudget(Number(e.target.value))}/></Field></div><div className="modal-footer"><button className="button" onClick={()=>setModal('')}>取消</button><button className="button primary" disabled={busy||!benchmarkSelection.length} onClick={()=>perform(async()=>{await post('/benchmarks/models',{profile_ids:benchmarkSelection,budget_cny:benchmarkBudget});setModal('')},'模型试评已提交，费用与输出将保留在记录中。')}>发起试评</button></div></Modal>}
  {['help','secrets'].includes(modal)&&<Modal title={modal==='help'?'如何使用研究室':'在本机保存密钥'} subtitle="先完成准备，再进入有边界的自动研究。" onClose={()=>setModal('')}><div className="modal-content help-content">{modal==='help'?<><h3>1. 先体验完整流程</h3><p>创建演示任务，确认环节 1 后查看提案与辩论，在环节 5 批准实验，再在环节 10 决定候选去向。演示使用合成数据与脚本。</p><h3>2. 配置真实研究的基础</h3><p>在数据与模型页登记供应商试样、模型和费用。核验数据口径，添加 2022 年底以前的论文或公开研报。</p><h3>3. 让证据决定下一步</h3><p>查看开发、验证与最终测试的独立报告。关闭网页不取消后台计算；关闭电脑后任务会在重新启动引擎后恢复。</p><h3>4. 留下完整研究档案</h3><p>导出报告用于阅读，导出 JSON 档案保留完整曲线、公式、版本与失败记录。</p></>:<><p>运行项目中的 <strong>配置密钥.cmd</strong>，输入凭据名称，再输入密钥。密钥不会显示，保存在 Windows 凭据管理器中。</p><table><thead><tr><th>用途</th><th>凭据名称</th></tr></thead><tbody><tr><td>云端模型</td><td>模型配置中填写的名称</td></tr><tr><td>米筐许可证</td><td>ricequant</td></tr><tr><td>Tushare token</td><td>tushare</td></tr><tr><td>资料检索</td><td>tavily</td></tr></tbody></table><p>不要把密钥粘贴进研究问题、资料正文或报告。网页不会要求你直接输入密钥。</p></>}</div><div className="modal-footer"><button className="button primary" onClick={()=>setModal('')}>知道了</button></div></Modal>}
 </div>
}

createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);
